BASE=Path(__file__).resolve().parents[1]; OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
D=[['拉丁语 delere → deletus','抹去、毁去 → 对应的过去分词形式']]
I=D+[['拉丁语 indelebilis','in- 不 + delebilis 可被抹去的：无法擦掉'],['法语借入或直接拉丁借入 → 英语 indeleble / indelible','英语早期拼写后来受 -ible 影响而改变']]
W=[
E('delete','英、美 /dɪˈliːt/','删除；删去','把某个项目从文字、名单或数据中去掉。','借自拉丁 deletus，是 delere“抹去”的过去分词。更早常解释为 de- + linere“涂抹”，经过“抹平蜡版上的字”走向消除；这一远源分析有争议，不能当作已经确定的谱系。',D+[['英语 delete','先说抹去、消除，后来常用于文字及计算机数据']],'编辑把一句话删掉，电脑把一个文件移出当前内容，动作都叫 delete。重点是“这个项目不再保留在这里”，并不承诺数据在所有备份中都彻底消失。','delete a file；delete a sentence；delete something from a list。','remove 范围很广，能移走桌椅；delete 主要针对记录、文字和数据。不要把 delete 硬拆成现代英语 de- 加一个不存在的 lete。',('I deleted the duplicate photos from the folder.','我把文件夹里重复的照片删掉了。'),('The editor suggested deleting the final sentence.','编辑建议删掉最后一句。'),sources=['https://www.merriam-webster.com/dictionary/delete','https://www.etymonline.com/word/delete','https://en.wiktionary.org/wiki/deleo#Latin']),
E('indelible','英、美 /ɪnˈdeləbl/','擦不掉的；难以忘怀的','像墨迹已经吃进纸里，擦不掉；印象也可以这样留在人心里。','拉丁 in-“不” + delebilis“可抹去的”，后者接 delere“抹去”。英语经法语或直接借拉丁词进入，早期有 indeleble，后来改为 -ible；不是英语 delete 加前后缀才第一次造出。',I,'indelible ink 是不易擦除的墨水；an indelible impression 是深到很难忘的印象。两种用法共用“留下了，抹不掉”这一画面，印象可以美好，也可以痛苦。','indelible ink；leave an indelible mark；make an indelible impression on someone。','permanent 泛指长期存在；indelible 更强调擦除、忘却不了。in- 在这里是否定，不是“在里面”。',('The labels were written in indelible ink.','这些标签是用不易擦除的墨水写的。'),('That first journey left an indelible impression on her.','第一次远行给她留下了难以忘怀的印象。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/indelible','https://www.etymonline.com/word/indelible']),
E('indelibly','英、美 /ɪnˈdeləbli/','不可磨灭地；牢牢地','形容某个标记或记忆留下之后，再也难以消去。','英语 indelible + -ly，-ble 结尾变成 -bly。副词继承“不可擦掉”的意思，不必重新把整个单词一路拆回拉丁语。',I+[['英语 indelible → indelibly','无法抹去的 → 无法抹去地']],'indelibly printed 可以说文字牢牢印在物品上；indelibly etched in memory 则把记忆比成刻痕。indelibly linked 说两个名字、事件或形象已经紧紧联系起来。','indelibly marked；indelibly etched in memory；indelibly linked with。','indelible 修饰名词，如 an indelible mark；indelibly 通常修饰 marked、linked、etched 等，说明这种留下或联系有多牢固。',('The serial number is indelibly marked on the metal case.','序列号牢牢地印在金属外壳上，难以擦掉。'),('The sound of that bell is indelibly etched in my memory.','那阵钟声深深刻在我的记忆里。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/indelibly','https://en.wiktionary.org/wiki/indelibly']),
E('liniment','英、美 /ˈlɪnəmənt/','外用擦剂；搽剂','一种擦在身体表面的药用液体，名字抓住的就是“涂抹”动作。','中古英语借晚期拉丁 linimentum，源于拉丁 linire“涂抹”（与 linere 对应）。-mentum 在拉丁语里构成事物或结果名词；不是现代英语 line“线” + -ment。',[['拉丁语 linere / linire','涂抹、搽上'],['晚期拉丁语 linimentum','涂抹用的物质'],['中古英语 lynyment → 英语 liniment','外用擦剂']],'想象瓶中的液体被擦到皮肤上，就能记住这个词。它通常用于描述减轻局部疼痛等用途的外用制剂，常有油性；并非所有护肤乳液都叫 liniment。','a bottle of liniment；a strong-smelling liniment；apply liniment。','liniment 是药用擦剂，lotion 的范围更广，可指护肤或药用乳液。名称描述制剂类型，不是口服药水。',('A bottle of liniment stood on the locker-room shelf.','更衣室的架子上放着一瓶擦剂。'),('The liniment had a sharp, medicinal smell.','这种擦剂有一股浓烈的药味。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/liniment','https://www.etymonline.com/word/liniment'])
]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text()); fam={r['id']:r['family'] for r in m['roots']}
ROOT=[dict(id='C0676',meaning='涂抹',core='lin- / line-：把一层东西抹到表面上。',image='手把油膏抹开，表面覆盖上一层；另一个相关联想是把蜡版字迹抹平。',intro='拉丁 linere、linire 表示涂抹，liniment 保留了这个动作。delete 一支常被解释为“涂抹到原来的字看不见”，但它与 linere 的远源关系有不同分析。本页把这条传统联系作为有争议的旁支，确定的删除词族另看 del-。',forms='liniment 的 lin- 接涂抹，不是 line“线”。delete、indelible 直接可追到 delere；再向前连到 linere，须保留争议，不能把词形相近当作证明。',branches=[['涂抹用的东西','liniment：外用擦剂'],['传统联系，远源有争议','delete、deletion；indelible、indelibly']],contrasts='“涂抹”的 line- 与“线、亚麻”来源的 line- 要分开学。抹平蜡版是理解传统词源说法的画面，不等于所有词源学者都确认 delete 必然走过这条路线。',practice='用 liniment 解释“涂抹”；再用 delete 与 indelible 对照“去掉”和“去不掉”。',words=list(fam['C0676']),exclude={},sources=['https://www.etymonline.com/word/liniment','https://www.etymonline.com/word/delete','https://en.wiktionary.org/wiki/deleo#Latin']),dict(id='C0310',meaning='抹去；删除',core='del- / delet-：让原本留下的内容消失。',image='纸上有一行字，编辑把它划掉；印象若深得划不掉，就是 indelible。',intro='从拉丁 delere“抹去、毁去”出发，这组词很容易用一对画面理解：delete 是删掉，indelible 是怎么也抹不掉。实际英语里，一个常出现在文件与编辑操作中，另一个常出现在墨迹、记忆与影响中。',forms='delete 接拉丁过去分词 deletus；deletion 是相应动作名词。indelible 里的 in- 是否定，-ible 对应能够被怎样；它是历史借词，不是今天临时把 delete 拼上前后缀。',branches=[['去掉内容','delete、deletion'],['无法抹去','indelible、indelibly']],contrasts='这组直接的拉丁来源较清楚；delere 再往前是否源于“涂抹”存在争议。学习时先掌握抹去这个稳定核心，不必把不确定远源背成定论。',practice='用 delete 造一句编辑文件的话，再用 indelible 造一句描述旅行记忆的话。',words=list(fam['C0310']),exclude={},sources=['https://www.merriam-webster.com/dictionary/delete','https://www.oxfordlearnersdictionaries.com/definition/english/indelible','https://en.wiktionary.org/wiki/deleo#Latin'])]
assert {x['word'] for x in W} == set(fam['C0676'])-{'deletion'}
assert all(x['word'] in m['owned_words'] for x in W)
for x in W: assert len(x['examples'])>=2 and all(len(n)==2 and all(isinstance(v,str) and v for v in n) for n in x['history'])
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_108_line_del.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('2 roots',len(W),'new',sum(len(r['words']) for r in ROOT),'root references',sum(len(x['examples']) for x in W),'examples')
